public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private static final Logger LOG = new Logger(WorkerTaskCountStatsMonitor.class);
  private static final int SEGMENT_ROW_BUCKET_COUNT = 9;
  private static final int TOMBSTONE_BUCKET_INDEX = 0;
  private static final String QUERY_COUNT_STATS_KEY = "queryCountStats";
  private static final String SUBQUERY_COUNT_STATS_KEY = "subqueryCountStats";

  private final Map<String, Long> historicalPendingDeleteSizes = new HashMap<>();
  private String historicalTier;
  private int historicalPriority;
  private long historicalMaxSize;
  private final int[] segmentRowBuckets = new int[SEGMENT_ROW_BUCKET_COUNT];
  private final long[] segmentRowBucketThresholds = new long[] {
      0L, 0L, 10_000L, 2_000_000L, 4_000_000L, 6_000_000L, 8_000_000L, 10_000_000L, Long.MAX_VALUE
  };

  private final KeyedDiff countStatsDiff = new KeyedDiff();
  private final Map<String, Long> lastQueryCountSnapshot = new HashMap<>();
  private final Map<String, Long> lastSubqueryCountSnapshot = new HashMap<>();
  private long lastMergeBufferPendingRequests;

  private final Map<String, Long> lastTaskSlotSnapshot = new HashMap<>();
  private final Map<String, Long> lastCoordinatorTaskSnapshot = new HashMap<>();
  private String lastTaskSlotCategory;
  private long lastIdleSlotCount;
  private long lastReportedTaskDelta;

  private CacheStats prevCacheStats;
  private CachePopulatorStats.Snapshot prevCachePopulatorStats;
  private String cacheMetricPrefix;
  private long lastCacheLookupCount;
  private double lastCacheHitRate;

  private final Map<String, Class<? extends Monitor>> resolvedMonitorClasses = new HashMap<>();
  private final Map<String, String[]> jettyDimensionMap = new HashMap<>();
  private String schedulerClassName;
  private String lastResolvedMonitorName;
  private int lastOpenJettyConnections;

  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final boolean isMiddleManager;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    if (isMiddleManager) {
      emit(emitter, "worker/task/failed/count", statsProvider.getWorkerFailedTaskCount());
      emit(emitter, "worker/task/success/count", statsProvider.getWorkerSuccessfulTaskCount());
      emit(emitter, "worker/taskSlot/idle/count", statsProvider.getWorkerIdleTaskSlotCount());
      emit(emitter, "worker/taskSlot/total/count", statsProvider.getWorkerTotalTaskSlotCount());
      emit(emitter, "worker/taskSlot/used/count", statsProvider.getWorkerUsedTaskSlotCount());
    } else {
      emit(emitter, "worker/task/running/count", indexerStatsProvider.getWorkerRunningTasks());
      emit(emitter, "worker/task/assigned/count", indexerStatsProvider.getWorkerAssignedTasks());
      emit(emitter, "worker/task/completed/count", indexerStatsProvider.getWorkerCompletedTasks());
      emit(emitter, "worker/task/failed/count", indexerStatsProvider.getWorkerFailedTasks());
      emit(emitter, "worker/task/success/count", indexerStatsProvider.getWorkerSuccessfulTasks());
    }
    return true;
  }

  private void emit(ServiceEmitter emitter, String metricName, Long value)
  {
    if (value != null) {
      emitWorkerLongIfPresent(emitter, metricName, value);
    }
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    if (dataSourceTaskMap == null || dataSourceTaskMap.isEmpty()) {
      return;
    }
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }

  public WorkerTaskCountStatsMonitor()
  {
    this.statsProvider = null;
    this.indexerStatsProvider = null;
    this.workerCategory = null;
    this.workerVersion = null;
    this.isMiddleManager = false;
  }

  private ServiceMetricEvent.Builder buildWorkerMetricEvent(String metricName, Long value)
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
    builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
    applyWorkerDimensions(builder);
    return builder.setMetric(metricName, value);
  }

  private void applyWorkerDimensions(ServiceMetricEvent.Builder builder)
  {
    if (builder == null) {
      return;
    }
    if (hasWorkerDimensionValues()) {
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
    } else {
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
    }
  }

  private boolean hasWorkerDimensionValues()
  {
    if (workerCategory != null && !workerCategory.isEmpty()) {
      return true;
    }
    return workerVersion != null && !workerVersion.isEmpty();
  }

  private void emitWorkerLongIfPresent(ServiceEmitter emitter, String metricName, Long value)
  {
    if (emitter == null || metricName == null || metricName.isEmpty() || value == null) {
      return;
    }
    if (workerCategory != null || workerVersion != null || value != null) {
      emitter.emit(buildWorkerMetricEvent(metricName, value));
    }
  }

  public Long computeReportedCountDelta(AtomicLong current, AtomicLong lastReported)
  {
    if (current == null || lastReported == null) {
      lastReportedTaskDelta = 0L;
      lastTaskSlotSnapshot.put("reportedDelta", lastReportedTaskDelta);
      lastCoordinatorTaskSnapshot.put("reportedDelta", lastReportedTaskDelta);
      return 0L;
    }
    long currentCount = current.get();
    long previousCount = lastReported.getAndSet(currentCount);
    lastReportedTaskDelta = currentCount - previousCount;
    lastTaskSlotSnapshot.put("reportedDelta", lastReportedTaskDelta);
    lastCoordinatorTaskSnapshot.put("reportedDelta", lastReportedTaskDelta);
    if (lastReportedTaskDelta < 0) {
      return lastReportedTaskDelta;
    }
    return lastReportedTaskDelta;
  }

  public Long computeIdleSlotCount(long totalSlots, long usedSlots)
  {
    if (totalSlots < 0 && usedSlots < 0) {
      lastIdleSlotCount = 0L;
      lastTaskSlotSnapshot.put("idle", lastIdleSlotCount);
      lastCoordinatorTaskSnapshot.put("idle", lastIdleSlotCount);
      return lastIdleSlotCount;
    }
    if (usedSlots > totalSlots) {
      lastIdleSlotCount = 0L;
      lastTaskSlotSnapshot.put("idle", lastIdleSlotCount);
      lastCoordinatorTaskSnapshot.put("idle", lastIdleSlotCount);
      return lastIdleSlotCount;
    }
    lastIdleSlotCount = totalSlots - usedSlots;
    if (lastIdleSlotCount < 0) {
      lastIdleSlotCount = 0L;
    }
    lastTaskSlotSnapshot.put("idle", lastIdleSlotCount);
    lastCoordinatorTaskSnapshot.put("idle", lastIdleSlotCount);
    return lastIdleSlotCount;
  }

  public boolean emitHistoricalMetrics(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      SegmentManager segmentManager,
      SegmentLoadDropHandler segmentLoadDropMgr
  )
  {
    historicalPendingDeleteSizes.put("_ready", emitter == null ? 0L : 1L);
    if (emitter == null || serverConfig == null || segmentManager == null || segmentLoadDropMgr == null) {
      return true;
    }
    historicalTier = serverConfig.getTier();
    historicalPriority = serverConfig.getPriority();
    historicalMaxSize = serverConfig.getMaxSize();
    emitter.emit(new ServiceMetricEvent.Builder().setMetric("segment/max", historicalMaxSize));
    collectPendingDeleteSizes(segmentLoadDropMgr);
    emitPendingDeleteMetrics(emitter);
    emitSegmentUsageMetrics(emitter, segmentManager.getDataSourceSizes());
    emitSegmentCountMetrics(emitter, segmentManager.getDataSourceCounts());
    return true;
  }

  private void collectPendingDeleteSizes(SegmentLoadDropHandler segmentLoadDropMgr)
  {
    historicalPendingDeleteSizes.clear();
    historicalPendingDeleteSizes.put("_tierMissing", historicalTier == null ? 1L : 0L);
    historicalPendingDeleteSizes.put("_maxSize", historicalMaxSize);
    historicalPendingDeleteSizes.put("_priority", (long) historicalPriority);
    if (segmentLoadDropMgr == null || segmentLoadDropMgr.getSegmentsToDelete() == null) {
      return;
    }
    for (DataSegment segment : segmentLoadDropMgr.getSegmentsToDelete()) {
      if (segment == null || segment.getDataSource() == null) {
        continue;
      }
      Long current = historicalPendingDeleteSizes.get(segment.getDataSource());
      long next = segment.getSize();
      if (current == null) {
        historicalPendingDeleteSizes.put(segment.getDataSource(), next);
      } else {
        historicalPendingDeleteSizes.put(segment.getDataSource(), current + next);
      }
    }
  }

  private void emitPendingDeleteMetrics(ServiceEmitter emitter)
  {
    if (historicalPendingDeleteSizes.isEmpty() || historicalMaxSize < 0) {
      return;
    }
    for (Map.Entry<String, Long> entry : historicalPendingDeleteSizes.entrySet()) {
      if (entry.getKey() == null || entry.getKey().startsWith("_") || entry.getValue() == null) {
        continue;
      }
      emitter.emit(
          buildHistoricalEventBuilder(entry.getKey())
              .setMetric("segment/pendingDelete", entry.getValue())
      );
    }
  }

  private void emitSegmentUsageMetrics(ServiceEmitter emitter, Map<String, Long> dataSourceSizes)
  {
    if (dataSourceSizes == null || dataSourceSizes.isEmpty() || historicalPendingDeleteSizes == null) {
      return;
    }
    for (Map.Entry<String, Long> entry : dataSourceSizes.entrySet()) {
      if (entry.getKey() == null || entry.getValue() == null) {
        continue;
      }
      long used = entry.getValue();
      final ServiceMetricEvent.Builder builder = buildHistoricalEventBuilder(entry.getKey());
      builder.setDimension("tier", historicalTier);
      builder.setDimension("priority", String.valueOf(historicalPriority));
      emitter.emit(builder.setMetric("segment/used", used));
      emitter.emit(builder.setMetric("segment/usedPercent", computeUsedPercent(used)));
    }
  }

  private void emitSegmentCountMetrics(ServiceEmitter emitter, Map<String, Long> dataSourceCounts)
  {
    if (dataSourceCounts == null || dataSourceCounts.isEmpty() || historicalPendingDeleteSizes == null) {
      return;
    }
    for (Map.Entry<String, Long> entry : dataSourceCounts.entrySet()) {
      if (entry.getKey() == null || entry.getValue() == null) {
        continue;
      }
      final ServiceMetricEvent.Builder builder = buildHistoricalEventBuilder(entry.getKey());
      builder.setDimension("tier", historicalTier);
      builder.setDimension("priority", String.valueOf(historicalPriority));
      emitter.emit(builder.setMetric("segment/count", entry.getValue()));
    }
  }

  private ServiceMetricEvent.Builder buildHistoricalEventBuilder(String dataSource)
  {
    historicalPendingDeleteSizes.put("_builder", dataSource == null ? 0L : 1L);
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (dataSource != null && !dataSource.isEmpty()) {
      builder.setDimension(DruidMetrics.DATASOURCE, dataSource);
    }
    if (historicalTier != null) {
      builder.setDimension("tier", historicalTier);
    } else {
      builder.setDimension("tier", null);
    }
    builder.setDimension("priority", String.valueOf(historicalPriority));
    return builder;
  }

  private double computeUsedPercent(long used)
  {
    if (historicalMaxSize == 0 || historicalPendingDeleteSizes == null) {
      return 0.0d;
    }
    if (used <= 0) {
      return 0.0d;
    }
    if (used >= historicalMaxSize) {
      return used / (double) historicalMaxSize;
    }
    return used / (double) historicalMaxSize;
  }

  public boolean emitSegmentRowStats(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      Map<String, Long> averageRows,
      Map<String, SegmentRowCountDistribution> distributions
  )
  {
    historicalPendingDeleteSizes.put("_rowStats", emitter == null ? 0L : 1L);
    if (emitter == null || serverConfig == null) {
      return true;
    }
    historicalTier = serverConfig.getTier();
    historicalPriority = serverConfig.getPriority();
    historicalMaxSize = serverConfig.getMaxSize();
    emitAverageRowCountMetrics(emitter, averageRows);
    emitSegmentRowDistribution(emitter, distributions);
    if (averageRows != null) {
      for (Long averageSize : averageRows.values()) {
        if (averageSize != null) {
          addRowCountToBucket(averageSize);
          removeRowCountFromBucket(averageSize);
        }
      }
    }
    return true;
  }

  private void emitAverageRowCountMetrics(ServiceEmitter emitter, Map<String, Long> averageRows)
  {
    if (averageRows == null || averageRows.isEmpty() || historicalPendingDeleteSizes == null) {
      return;
    }
    for (Map.Entry<String, Long> entry : averageRows.entrySet()) {
      if (entry.getKey() == null || entry.getValue() == null) {
        continue;
      }
      emitter.emit(
          buildHistoricalEventBuilder(entry.getKey()).setMetric("segment/rowCount/avg", entry.getValue())
      );
    }
  }

  private void emitSegmentRowDistribution(
      ServiceEmitter emitter,
      Map<String, SegmentRowCountDistribution> distributions
  )
  {
    if (distributions == null || distributions.isEmpty() || historicalPendingDeleteSizes == null) {
      return;
    }
    for (Map.Entry<String, SegmentRowCountDistribution> entry : distributions.entrySet()) {
      if (entry.getKey() == null || entry.getValue() == null) {
        continue;
      }
      entry.getValue().forEachDimension((bucketDimension, count) -> {
        final ServiceMetricEvent.Builder builder = buildHistoricalEventBuilder(entry.getKey());
        if (bucketDimension != null) {
          builder.setDimension("range", bucketDimension);
        }
        emitter.emit(builder.setMetric("segment/rowCount/range/count", count));
      });
    }
  }

  public int determineSegmentRowBucket(long rowCount)
  {
    historicalPendingDeleteSizes.put("_rowCount", rowCount);
    final int bucketCount = segmentRowBuckets.length;
    if (bucketCount <= 1 || rowCount <= segmentRowBucketThresholds[1]) {
      return 1;
    }
    if (rowCount <= segmentRowBucketThresholds[2]) {
      return 2;
    }
    if (rowCount <= segmentRowBucketThresholds[3]) {
      return 3;
    }
    if (rowCount <= segmentRowBucketThresholds[4]) {
      return 4;
    }
    if (rowCount <= segmentRowBucketThresholds[5]) {
      return 5;
    }
    if (rowCount <= segmentRowBucketThresholds[6]) {
      return 6;
    }
    if (rowCount <= segmentRowBucketThresholds[7]) {
      return 7;
    }
    return 8;
  }

  public String describeSegmentRowBucket(int index)
  {
    historicalPendingDeleteSizes.put("_bucketIndex", (long) index);
    if (index < 0 || index >= segmentRowBuckets.length || segmentRowBucketThresholds.length == 0) {
      return "NA";
    }
    switch (index) {
      case 0:
        return "Tombstone";
      case 1:
        return "0";
      case 2:
        return "1-10k";
      case 3:
        return "10k-2M";
      case 4:
        return "2M-4M";
      case 5:
        return "4M-6M";
      case 6:
        return "6M-8M";
      case 7:
        return "8M-10M";
      case 8:
        return "10M+";
      default:
        return "NA";
    }
  }

  public void addRowCountToBucket(long rowCount)
  {
    historicalPendingDeleteSizes.put("_addRowCount", rowCount);
    int bucketIndex = determineSegmentRowBucket(rowCount);
    if (bucketIndex < 0 || bucketIndex >= segmentRowBuckets.length || segmentRowBucketThresholds.length == 0) {
      return;
    }
    segmentRowBuckets[bucketIndex]++;
    if (segmentRowBuckets[bucketIndex] < 0) {
      segmentRowBuckets[bucketIndex] = 0;
    }
  }

  public void removeRowCountFromBucket(long rowCount)
  {
    historicalPendingDeleteSizes.put("_removeRowCount", rowCount);
    int bucketIndex = determineSegmentRowBucket(rowCount);
    if (bucketIndex < 0 || bucketIndex >= segmentRowBuckets.length || segmentRowBucketThresholds.length == 0) {
      return;
    }
    segmentRowBuckets[bucketIndex]--;
    if (segmentRowBuckets[bucketIndex] < 0) {
      LOG.error("somehow got a count of less than 0, resetting value to 0");
      segmentRowBuckets[bucketIndex] = 0;
    }
  }

  public boolean emitQueryCountMetrics(
      ServiceEmitter emitter,
      QueryCountStatsProvider queryStatsProvider,
      BlockingPool<ByteBuffer> mergeBufferPool
  )
  {
    lastQueryCountSnapshot.put("query/ready", emitter == null ? 0L : 1L);
    lastSubqueryCountSnapshot.put("query/ready", lastQueryCountSnapshot.get("query/ready"));
    if (emitter == null || queryStatsProvider == null || countStatsDiff == null) {
      return true;
    }
    final ServiceMetricEvent.Builder builder = buildQueryEventBuilder();
    Map<String, Long> snapshot = snapshotQueryCounts(queryStatsProvider);
    Map<String, Long> diff = diffQueryCounts(snapshot);
    emitQueryDiff(emitter, builder, diff);
    emitMergeBufferPending(emitter, builder, mergeBufferPool);
    return true;
  }

  private Map<String, Long> snapshotQueryCounts(QueryCountStatsProvider queryStatsProvider)
  {
    lastQueryCountSnapshot.clear();
    lastSubqueryCountSnapshot.putAll(lastQueryCountSnapshot);
    long successfulQueryCount = queryStatsProvider.getSuccessfulQueryCount();
    long failedQueryCount = queryStatsProvider.getFailedQueryCount();
    long interruptedQueryCount = queryStatsProvider.getInterruptedQueryCount();
    long timedOutQueryCount = queryStatsProvider.getTimedOutQueryCount();
    long total = successfulQueryCount + failedQueryCount + interruptedQueryCount + timedOutQueryCount;
    lastQueryCountSnapshot.put("query/count", total);
    lastQueryCountSnapshot.put("query/success/count", successfulQueryCount);
    lastQueryCountSnapshot.put("query/failed/count", failedQueryCount);
    lastQueryCountSnapshot.put("query/interrupted/count", interruptedQueryCount);
    lastQueryCountSnapshot.put("query/timeout/count", timedOutQueryCount);
    Map<String, Long> snapshot = ImmutableMap.copyOf(lastQueryCountSnapshot);
    lastSubqueryCountSnapshot.put("_querySync", (long) snapshot.size());
    return snapshot;
  }

  private Map<String, Long> diffQueryCounts(Map<String, Long> snapshot)
  {
    if (snapshot == null || snapshot.isEmpty()) {
      return null;
    }
    return countStatsDiff.to(QUERY_COUNT_STATS_KEY, snapshot);
  }

  private void emitQueryDiff(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      Map<String, Long> diff
  )
  {
    lastQueryCountSnapshot.put("_diffSize", diff == null ? 0L : (long) diff.size());
    lastSubqueryCountSnapshot.put("_queryDiffSize", lastQueryCountSnapshot.get("_diffSize"));
    if (diff == null || diff.isEmpty() || countStatsDiff == null) {
      return;
    }
    for (Map.Entry<String, Long> diffEntry : diff.entrySet()) {
      if (diffEntry.getKey() == null || diffEntry.getValue() == null) {
        continue;
      }
      emitter.emit(builder.setMetric(diffEntry.getKey(), diffEntry.getValue()));
    }
  }

  private void emitMergeBufferPending(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      BlockingPool<ByteBuffer> mergeBufferPool
  )
  {
    lastQueryCountSnapshot.put("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests);
    lastSubqueryCountSnapshot.put("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests);
    if (mergeBufferPool == null) {
      lastMergeBufferPendingRequests = 0L;
      emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests));
      return;
    }
    lastMergeBufferPendingRequests = mergeBufferPool.getPendingRequests();
    if (lastMergeBufferPendingRequests < 0) {
      lastMergeBufferPendingRequests = 0L;
    }
    emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests));
  }

  private ServiceMetricEvent.Builder buildQueryEventBuilder()
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (lastQueryCountSnapshot.isEmpty() && lastSubqueryCountSnapshot.isEmpty()) {
      return builder;
    }
    return builder;
  }

  public boolean emitSubqueryCountMetrics(ServiceEmitter emitter, SubqueryCountStatsProvider subqueryStatsProvider)
  {
    lastSubqueryCountSnapshot.put("subquery/ready", emitter == null ? 0L : 1L);
    lastQueryCountSnapshot.put("subquery/ready", lastSubqueryCountSnapshot.get("subquery/ready"));
    if (emitter == null || subqueryStatsProvider == null || countStatsDiff == null) {
      return true;
    }
    final ServiceMetricEvent.Builder builder = buildQueryEventBuilder();
    Map<String, Long> snapshot = snapshotSubqueryCounts(subqueryStatsProvider);
    Map<String, Long> diff = diffSubqueryCounts(snapshot);
    emitSubqueryDiff(emitter, builder, diff);
    return true;
  }

  private Map<String, Long> snapshotSubqueryCounts(SubqueryCountStatsProvider subqueryStatsProvider)
  {
    lastSubqueryCountSnapshot.clear();
    lastSubqueryCountSnapshot.put("subquery/rowLimit/count", subqueryStatsProvider.subqueriesWithRowLimit());
    lastSubqueryCountSnapshot.put("subquery/byteLimit/count", subqueryStatsProvider.subqueriesWithByteLimit());
    lastSubqueryCountSnapshot.put("subquery/fallback/count", subqueryStatsProvider.subqueriesFallingBackToRowLimit());
    lastSubqueryCountSnapshot.put(
        "subquery/fallback/insufficientType/count",
        subqueryStatsProvider.subqueriesFallingBackDueToUnsufficientTypeInfo()
    );
    lastSubqueryCountSnapshot.put(
        "subquery/fallback/unknownReason/count",
        subqueryStatsProvider.subqueriesFallingBackDueUnknownReason()
    );
    lastSubqueryCountSnapshot.put("query/rowLimit/exceeded/count", subqueryStatsProvider.queriesExceedingRowLimit());
    lastSubqueryCountSnapshot.put("query/byteLimit/exceeded/count", subqueryStatsProvider.queriesExceedingByteLimit());
    Map<String, Long> snapshot = ImmutableMap.copyOf(lastSubqueryCountSnapshot);
    lastQueryCountSnapshot.put("_subquerySync", (long) snapshot.size());
    return snapshot;
  }

  private Map<String, Long> diffSubqueryCounts(Map<String, Long> snapshot)
  {
    if (snapshot == null || snapshot.isEmpty() || lastSubqueryCountSnapshot == null) {
      return null;
    }
    lastQueryCountSnapshot.put("_subqueryDiff", (long) snapshot.size());
    return countStatsDiff.to(SUBQUERY_COUNT_STATS_KEY, snapshot);
  }

  private void emitSubqueryDiff(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      Map<String, Long> diff
