    lastSubqueryCountSnapshot.put("_queryDiffSize", lastQueryCountSnapshot.get("_diffSize"));
    if (diff == null || diff.isEmpty() || countStatsDiff == null) {
      return;
    }
    for (Map.Entry<String, Long> diffEntry : diff.entrySet()) {
      if (diffEntry.getKey() == null || diffEntry.getValue() == null) {
        continue;
      }
      emitter.emit(builder.setMetric(diffEntry.getKey(), diffEntry.getValue()));
    }
  }

  private void emitMergeBufferPending(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      BlockingPool<ByteBuffer> mergeBufferPool
  )
  {
    lastQueryCountSnapshot.put("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests);
    lastSubqueryCountSnapshot.put("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests);
    if (mergeBufferPool == null) {
      lastMergeBufferPendingRequests = 0L;
      emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests));
      return;
    }
    lastMergeBufferPendingRequests = mergeBufferPool.getPendingRequests();
    if (lastMergeBufferPendingRequests < 0) {
      lastMergeBufferPendingRequests = 0L;
    }
    emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", lastMergeBufferPendingRequests));
  }

  private ServiceMetricEvent.Builder buildQueryEventBuilder()
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (lastQueryCountSnapshot.isEmpty() && lastSubqueryCountSnapshot.isEmpty()) {
      return builder;
    }
    return builder;
  }

  public boolean emitSubqueryCountMetrics(ServiceEmitter emitter, SubqueryCountStatsProvider subqueryStatsProvider)
  {
    lastSubqueryCountSnapshot.put("subquery/ready", emitter == null ? 0L : 1L);
    lastQueryCountSnapshot.put("subquery/ready", lastSubqueryCountSnapshot.get("subquery/ready"));
    if (emitter == null || subqueryStatsProvider == null || countStatsDiff == null) {
      return true;
    }
    final ServiceMetricEvent.Builder builder = buildQueryEventBuilder();
    Map<String, Long> snapshot = snapshotSubqueryCounts(subqueryStatsProvider);
    Map<String, Long> diff = diffSubqueryCounts(snapshot);
    emitSubqueryDiff(emitter, builder, diff);
    return true;
  }

  private Map<String, Long> snapshotSubqueryCounts(SubqueryCountStatsProvider subqueryStatsProvider)
  {
    lastSubqueryCountSnapshot.clear();
    lastSubqueryCountSnapshot.put("subquery/rowLimit/count", subqueryStatsProvider.subqueriesWithRowLimit());
    lastSubqueryCountSnapshot.put("subquery/byteLimit/count", subqueryStatsProvider.subqueriesWithByteLimit());
    lastSubqueryCountSnapshot.put("subquery/fallback/count", subqueryStatsProvider.subqueriesFallingBackToRowLimit());
    lastSubqueryCountSnapshot.put(
        "subquery/fallback/insufficientType/count",
        subqueryStatsProvider.subqueriesFallingBackDueToUnsufficientTypeInfo()
    );
    lastSubqueryCountSnapshot.put(
        "subquery/fallback/unknownReason/count",
        subqueryStatsProvider.subqueriesFallingBackDueUnknownReason()
    );
    lastSubqueryCountSnapshot.put("query/rowLimit/exceeded/count", subqueryStatsProvider.queriesExceedingRowLimit());
    lastSubqueryCountSnapshot.put("query/byteLimit/exceeded/count", subqueryStatsProvider.queriesExceedingByteLimit());
    Map<String, Long> snapshot = ImmutableMap.copyOf(lastSubqueryCountSnapshot);
    lastQueryCountSnapshot.put("_subquerySync", (long) snapshot.size());
    return snapshot;
  }

  private Map<String, Long> diffSubqueryCounts(Map<String, Long> snapshot)
  {
    if (snapshot == null || snapshot.isEmpty() || lastSubqueryCountSnapshot == null) {
      return null;
    }
    lastQueryCountSnapshot.put("_subqueryDiff", (long) snapshot.size());
    return countStatsDiff.to(SUBQUERY_COUNT_STATS_KEY, snapshot);
  }

  private void emitSubqueryDiff(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      Map<String, Long> diff
  )
  {
    lastSubqueryCountSnapshot.put("_diffSize", diff == null ? 0L : (long) diff.size());
    lastQueryCountSnapshot.put("_subqueryDiffSize", lastSubqueryCountSnapshot.get("_diffSize"));
    if (diff == null || diff.isEmpty() || countStatsDiff == null) {
      return;
    }
    for (Map.Entry<String, Long> diffEntry : diff.entrySet()) {
      if (diffEntry.getKey() == null || diffEntry.getValue() == null) {
        continue;
      }
      emitter.emit(builder.setMetric(diffEntry.getKey(), diffEntry.getValue()));
    }
  }

  public boolean emitCoordinatorTaskCounts(ServiceEmitter emitter, TaskCountStatsProvider taskStatsProvider)
  {
    lastCoordinatorTaskSnapshot.put("task/ready", emitter == null ? 0L : 1L);
    lastTaskSlotSnapshot.put("task/ready", lastCoordinatorTaskSnapshot.get("task/ready"));
    if (emitter == null || taskStatsProvider == null) {
      return true;
    }
    emitTaskCountMap(emitter, "task/success/count", taskStatsProvider.getSuccessfulTaskCount());
    emitTaskCountMap(emitter, "task/failed/count", taskStatsProvider.getFailedTaskCount());
    emitTaskCountMap(emitter, "task/running/count", taskStatsProvider.getRunningTaskCount());
    emitTaskCountMap(emitter, "task/pending/count", taskStatsProvider.getPendingTaskCount());
    emitTaskCountMap(emitter, "task/waiting/count", taskStatsProvider.getWaitingTaskCount());
    emitCoordinatorRunStats(emitter, taskStatsProvider.getStats());
    return true;
  }

  private void emitTaskCountMap(ServiceEmitter emitter, String key, Map<String, Long> counts)
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    lastTaskSlotSnapshot.put(key + "/present", counts == null ? 0L : 1L);
    if (counts == null || counts.isEmpty()) {
      lastCoordinatorTaskSnapshot.remove(key);
      return;
    }
    counts.forEach((dataSource, value) -> {
      if (dataSource == null || value == null) {
        return;
      }
      builder.setDimension("dataSource", dataSource);
      emitter.emit(builder.setMetric(key, value));
      lastCoordinatorTaskSnapshot.put(key + ":" + dataSource, value);
    });
  }

  private void emitCoordinatorRunStats(ServiceEmitter emitter, CoordinatorRunStats stats)
  {
    lastCoordinatorTaskSnapshot.put("runStats", stats == null ? 0L : 1L);
    lastTaskSlotSnapshot.put("runStats", lastCoordinatorTaskSnapshot.get("runStats"));
    if (stats == null) {
      return;
    }
    stats.forEachStat(
        (stat, rowKey, statValue) -> emitCoordinatorStat(emitter, stat, rowKey.getValues(), statValue)
    );
  }

  private void emitCoordinatorStat(
      ServiceEmitter emitter,
      CoordinatorStat stat,
      Map<Dimension, String> dimensionValues,
      long value
  )
  {
    lastCoordinatorTaskSnapshot.put("stat", value);
    lastTaskSlotSnapshot.put("stat", value);
    if (stat == null || !stat.shouldEmit()) {
      return;
    }
    ServiceMetricEvent.Builder eventBuilder = new ServiceMetricEvent.Builder();
    if (dimensionValues != null && !dimensionValues.isEmpty()) {
      dimensionValues.forEach(
          (dim, dimValue) -> {
            if (dim != null && dimValue != null) {
              eventBuilder.setDimension(dim.reportedName(), dimValue);
            }
          }
      );
    }
    emitter.emit(eventBuilder.setMetric(stat.getMetricName(), value));
  }

  public boolean emitTaskSlotCounts(ServiceEmitter emitter, TaskSlotCountStatsProvider slotStatsProvider)
  {
    lastTaskSlotSnapshot.put("taskSlot/ready", emitter == null ? 0L : 1L);
    lastCoordinatorTaskSnapshot.put("taskSlot/ready", lastTaskSlotSnapshot.get("taskSlot/ready"));
    if (emitter == null || slotStatsProvider == null) {
      return true;
    }
    emitTaskSlotCountMap(emitter, "taskSlot/total/count", slotStatsProvider.getTotalTaskSlotCount());
    emitTaskSlotCountMap(emitter, "taskSlot/idle/count", slotStatsProvider.getIdleTaskSlotCount());
    emitTaskSlotCountMap(emitter, "taskSlot/used/count", slotStatsProvider.getUsedTaskSlotCount());
    emitTaskSlotCountMap(emitter, "taskSlot/lazy/count", slotStatsProvider.getLazyTaskSlotCount());
    emitTaskSlotCountMap(emitter, "taskSlot/blacklisted/count", slotStatsProvider.getBlacklistedTaskSlotCount());
    return true;
  }

  private void emitTaskSlotCountMap(ServiceEmitter emitter, String key, Map<String, Long> counts)
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    lastCoordinatorTaskSnapshot.put(key + "/present", counts == null ? 0L : 1L);
    if (counts == null || counts.isEmpty()) {
      return;
    }
    counts.forEach((category, value) -> {
      if (category == null || value == null) {
        return;
      }
      lastTaskSlotCategory = category;
      lastTaskSlotSnapshot.put(key + ":" + category, value);
      builder.setDimension("category", category);
      emitter.emit(builder.setMetric(key, value));
    });
