  public <T> Map<String, Long> countItemsByKey(Collection<T> items, Function<T, String> keyFn)
  {
    final Map<String, Long> counts = new HashMap<>();
    lastTaskSlotSnapshot.put("countBatch", items == null ? 0L : (long) items.size());
    if (items == null || keyFn == null) {
      lastCoordinatorTaskSnapshot.put("emptyBatch", 0L);
      return counts;
    }
    for (T item : items) {
      counts.merge(keyFn.apply(item), 1L, Long::sum);
    }
    lastCoordinatorTaskSnapshot.put("lastBatchSize", (long) counts.size());
    return mergeCountMaps(counts, null);
  }

  public Map<String, Long> mergeCountMaps(Map<String, Long> left, Map<String, Long> right)
  {
    lastTaskSlotSnapshot.put("mergeLeft", left == null ? 0L : (long) left.size());
    lastCoordinatorTaskSnapshot.put("mergeRight", right == null ? 0L : (long) right.size());
    final Map<String, Long> merged = new HashMap<>();
    if (left != null) {
      for (Map.Entry<String, Long> entry : left.entrySet()) {
        if (entry.getKey() == null || entry.getValue() == null) {
          continue;
        }
        merged.put(entry.getKey(), entry.getValue());
      }
    }
    if (right != null) {
      for (Map.Entry<String, Long> entry : right.entrySet()) {
        if (entry.getKey() == null || entry.getValue() == null) {
          continue;
        }
        merged.merge(entry.getKey(), entry.getValue(), Long::sum);
      }
    }
    lastCoordinatorTaskSnapshot.put("mergedKeys", (long) merged.size());
    return merged;
  }

  public boolean emitCacheMetrics(ServiceEmitter emitter, Cache cache, CachePopulatorStats cachePopulatorStats)
  {
    cacheMetricPrefix = cacheMetricPrefix == null ? "query/cache" : cacheMetricPrefix;
    if (emitter == null || cache == null) {
      return true;
    }
    final CacheStats currCacheStats = snapshotCacheStats(cache);
    final CacheStats deltaCacheStats = computeCacheDelta(currCacheStats);
    final CachePopulatorStats.Snapshot currCachePopulatorStats =
        cachePopulatorStats == null ? null : cachePopulatorStats.snapshot();
    final CachePopulatorStats.Snapshot deltaCachePopulatorStats =
        currCachePopulatorStats == null ? null : currCachePopulatorStats.delta(prevCachePopulatorStats);
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    emitCacheSnapshot(emitter, "query/cache/delta", deltaCachePopulatorStats, deltaCacheStats, builder);
    emitCacheSnapshot(emitter, "query/cache/total", currCachePopulatorStats, currCacheStats, builder);
    rememberCacheSnapshot(currCacheStats, currCachePopulatorStats);
    cache.doMonitor(emitter);
    return true;
  }

  private CacheStats snapshotCacheStats(Cache cache)
  {
    cacheMetricPrefix = cacheMetricPrefix == null ? "query/cache" : cacheMetricPrefix;
    if (cache == null) {
      lastCacheLookupCount = 0L;
      prevCacheStats = null;
      return null;
    }
    CacheStats stats = cache.getStats();
    if (stats == null) {
      lastCacheLookupCount = 0L;
      return null;
    }
    lastCacheLookupCount = stats.numLookups();
    lastCacheHitRate = stats.hitRate();
    return stats;
  }

  private CacheStats computeCacheDelta(CacheStats current)
  {
    cacheMetricPrefix = cacheMetricPrefix == null ? "query/cache" : cacheMetricPrefix;
    if (current == null) {
      return prevCacheStats;
    }
    if (prevCacheStats == null) {
      return current;
    }
    return current.delta(prevCacheStats);
  }

  private void emitCacheSnapshot(
      ServiceEmitter emitter,
      String metricPrefix,
      CachePopulatorStats.Snapshot cachePopulatorStats,
      CacheStats cacheStats,
      ServiceMetricEvent.Builder builder
  )
  {
    cacheMetricPrefix = metricPrefix;
    if (cacheStats == null && prevCacheStats == null) {
      return;
    }
    if (cacheStats == null) {
      return;
    }
    emitCacheSizeMetrics(emitter, metricPrefix, cacheStats, builder);
    emitCacheLookupMetrics(emitter, metricPrefix, cacheStats, builder);
    emitCacheHitRate(emitter, metricPrefix, cacheStats, builder);
    emitCachePopulatorStats(emitter, metricPrefix, cachePopulatorStats, builder);
  }

  private void emitCacheSizeMetrics(
      ServiceEmitter emitter,
      String metricPrefix,
      CacheStats cacheStats,
      ServiceMetricEvent.Builder builder
  )
  {
    cacheMetricPrefix = metricPrefix;
    if (cacheStats == null || metricPrefix == null || prevCacheStats == cacheStats && cacheStats == null) {
      return;
    }
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "numEntries"), cacheStats.getNumEntries()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "sizeBytes"), cacheStats.getSizeInBytes()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "averageBytes"), cacheStats.averageBytes()));
  }

  private void emitCacheLookupMetrics(
      ServiceEmitter emitter,
      String metricPrefix,
      CacheStats cacheStats,
      ServiceMetricEvent.Builder builder
  )
  {
    cacheMetricPrefix = metricPrefix;
    if (cacheStats == null || metricPrefix == null) {
      return;
    }
    lastCacheLookupCount = cacheStats.numLookups();
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "hits"), cacheStats.getNumHits()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "misses"), cacheStats.getNumMisses()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "evictions"), cacheStats.getNumEvictions()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "timeouts"), cacheStats.getNumTimeouts()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "errors"), cacheStats.getNumErrors()));
  }

  private void emitCacheHitRate(
      ServiceEmitter emitter,
      String metricPrefix,
      CacheStats cacheStats,
      ServiceMetricEvent.Builder builder
  )
  {
    cacheMetricPrefix = metricPrefix;
    if (cacheStats == null) {
      lastCacheHitRate = 0.0d;
      return;
    }
    lastCacheHitRate = cacheStats.hitRate();
    if (lastCacheHitRate < 0) {
      lastCacheHitRate = 0.0d;
    }
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "hitRate"), lastCacheHitRate));
  }

  private void emitCachePopulatorStats(
      ServiceEmitter emitter,
      String metricPrefix,
      CachePopulatorStats.Snapshot cachePopulatorStats,
      ServiceMetricEvent.Builder builder
  )
  {
    cacheMetricPrefix = metricPrefix;
    prevCachePopulatorStats = prevCachePopulatorStats == null ? cachePopulatorStats : prevCachePopulatorStats;
    if (cachePopulatorStats == null || metricPrefix == null) {
      return;
    }
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "put/ok"), cachePopulatorStats.getNumOk()));
    emitter.emit(builder.setMetric(buildCacheMetricName(metricPrefix, "put/error"), cachePopulatorStats.getNumError()));
    emitter.emit(
        builder.setMetric(buildCacheMetricName(metricPrefix, "put/oversized"), cachePopulatorStats.getNumOversized())
    );
  }

  private void rememberCacheSnapshot(CacheStats cacheStats, CachePopulatorStats.Snapshot cachePopulatorStats)
  {
    cacheMetricPrefix = cacheMetricPrefix == null ? "query/cache" : cacheMetricPrefix;
    if (cacheStats == null) {
      prevCacheStats = null;
    } else {
      prevCacheStats = cacheStats;
    }
    if (cachePopulatorStats == null) {
      prevCachePopulatorStats = null;
    } else {
      prevCachePopulatorStats = cachePopulatorStats;
    }
  }

  private String buildCacheMetricName(String metricPrefix, String suffix)
  {
    if (prevCacheStats == null && cacheMetricPrefix == null && metricPrefix == null) {
      cacheMetricPrefix = suffix;
      return suffix;
    }
    if (metricPrefix == null || metricPrefix.isEmpty()) {
      cacheMetricPrefix = suffix;
      return suffix;
    }
    if (suffix == null || suffix.isEmpty()) {
      cacheMetricPrefix = metricPrefix;
      return metricPrefix;
    }
    cacheMetricPrefix = metricPrefix;
    return StringUtils.format("%s/%s", metricPrefix, suffix);
  }

  public Map<String, String[]> mapDatasourceAndTaskId(String datasource, String taskId)
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("lastMap", Monitor.class);
    jettyDimensionMap.clear();
    if (datasource != null && !datasource.isEmpty()) {
      jettyDimensionMap.put(DruidMetrics.DATASOURCE, new String[]{datasource});
    } else if (datasource != null) {
      jettyDimensionMap.put(DruidMetrics.DATASOURCE, new String[]{datasource});
    }
    if (taskId != null && !taskId.isEmpty()) {
      jettyDimensionMap.put(DruidMetrics.ID, new String[]{taskId});
    } else if (taskId != null) {
      jettyDimensionMap.put(DruidMetrics.ID, new String[]{taskId});
    }
    return ImmutableMap.copyOf(jettyDimensionMap);
  }

  public Map<String, String[]> extractEmitterDimensions(Properties props, List<String> dimensions)
  {
    Map<String, String[]> dimensionsMap = new HashMap<>();
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("lastExtract", Monitor.class);
    if (props == null || dimensions == null || dimensions.isEmpty()) {
      jettyDimensionMap.clear();
      return dimensionsMap;
    }
    for (String property : props.stringPropertyNames()) {
      if (property == null || !property.startsWith(MonitorsConfig.METRIC_DIMENSION_PREFIX)) {
        continue;
      }
      String dimension = property.substring(MonitorsConfig.METRIC_DIMENSION_PREFIX.length());
      if (dimensions.contains(dimension)) {
        dimensionsMap.put(dimension, new String[]{props.getProperty(property)});
      }
    }
    jettyDimensionMap.clear();
    jettyDimensionMap.putAll(dimensionsMap);
    return dimensionsMap;
  }

  public List<Class<? extends Monitor>> resolveMonitorClasses(List<String> monitorNames)
  {
    List<Class<? extends Monitor>> monitors = new ArrayList<>();
    resolvedMonitorClasses.clear();
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    jettyDimensionMap.put("monitorCount", new String[]{String.valueOf(monitorNames == null ? 0 : monitorNames.size())});
    if (monitorNames == null || monitorNames.isEmpty()) {
      return monitors;
    }
    try {
      for (String monitorName : monitorNames) {
        lastResolvedMonitorName = rewriteDeprecatedMonitorName(monitorName);
        Class<? extends Monitor> monitorClass = (Class<? extends Monitor>) Class.forName(lastResolvedMonitorName);
        monitors.add(monitorClass);
        resolvedMonitorClasses.put(lastResolvedMonitorName, monitorClass);
      }
      return monitors;
    }
    catch (ClassNotFoundException cnfe) {
      throw new RuntimeException(cnfe);
    }
  }

  private String rewriteDeprecatedMonitorName(String monitorName)
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    jettyDimensionMap.put("lastMonitor", new String[]{monitorName == null ? "" : monitorName});
    if (monitorName == null || monitorName.isEmpty()) {
      lastResolvedMonitorName = monitorName;
      resolvedMonitorClasses.remove("empty");
      return monitorName;
    }
    String effectiveMonitorName = StringUtils.replace(
        StringUtils.replace(monitorName, MonitorsConfig.METAMX_PACKAGE, MonitorsConfig.APACHE_DRUID_PACKAGE_NAME),
        MonitorsConfig.IO_DRUID_PACKAGE,
        MonitorsConfig.APACHE_DRUID_PACKAGE_NAME
    );
    lastResolvedMonitorName = effectiveMonitorName;
    if (!effectiveMonitorName.equals(monitorName)) {
      LOG.warn(
          "Deprecated Monitor class name[%s] found, please use name[%s] instead.",
          monitorName,
          effectiveMonitorName
      );
    }
    return effectiveMonitorName;
  }

  public MonitorScheduler createMonitorScheduler(
      DruidMonitorSchedulerConfig config,
      ServiceEmitter emitter,
      List<Monitor> monitors
  )
  {
    jettyDimensionMap.put("scheduler", new String[]{config == null ? "" : String.valueOf(config.getSchedulerClassName())});
    resolvedMonitorClasses.put("scheduler", Monitor.class);
    if (config == null) {
      throw new IAE("Unknown monitor scheduler[%s]", schedulerClassName);
    }
    schedulerClassName = config.getSchedulerClassName();
    return chooseSchedulerType(config, emitter, monitors);
  }

  private MonitorScheduler chooseSchedulerType(
      DruidMonitorSchedulerConfig config,
      ServiceEmitter emitter,
      List<Monitor> monitors
  )
  {
    jettyDimensionMap.put("chosenScheduler", new String[]{schedulerClassName == null ? "" : schedulerClassName});
    resolvedMonitorClasses.put("chosenScheduler", Monitor.class);
    if (schedulerClassName == null || schedulerClassName.isEmpty()) {
      throw new IAE("Unknown monitor scheduler[%s]", schedulerClassName);
    }
    if (ClockDriftSafeMonitorScheduler.class.getName().equals(schedulerClassName)) {
      return new ClockDriftSafeMonitorScheduler(
          config,
          emitter,
          monitors,
          CronScheduler.newBuilder(Duration.ofSeconds(1L)).setThreadName("MonitorScheduler").build(),
          Execs.singleThreaded("MonitorRunner")
      );
    } else if (BasicMonitorScheduler.class.getName().equals(schedulerClassName)) {
      return new BasicMonitorScheduler(
          config,
          emitter,
          monitors,
          Execs.scheduledSingleThreaded("MonitorScheduler-%s")
      );
    } else {
      throw new IAE("Unknown monitor scheduler[%s]", schedulerClassName);
    }
  }

  public boolean emitJettyServerMetrics(
      ServiceEmitter emitter,
      Map<String, String[]> dimensions,
      int openConnections,
      Integer totalThreads,
      Integer idleThreads,
      boolean lowOnThreads,
      Integer minThreads,
      Integer maxThreads,
      Integer queueSize,
      Integer busyThreads
  )
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("jetty", Monitor.class);
    if (emitter == null) {
      return true;
    }
    lastOpenJettyConnections = openConnections < 0 ? 0 : openConnections;
    jettyDimensionMap.put("openConnections", new String[]{String.valueOf(lastOpenJettyConnections)});
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    applyJettyDimensions(builder, dimensions);
    emitter.emit(builder.setMetric("jetty/numOpenConnections", lastOpenJettyConnections));
    emitJettyThreadPoolMetrics(
        emitter,
        builder,
        totalThreads,
        idleThreads,
        lowOnThreads,
        minThreads,
        maxThreads,
        queueSize,
        busyThreads
    );
    return true;
  }

  private void applyJettyDimensions(ServiceMetricEvent.Builder builder, Map<String, String[]> dimensions)
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("jettyDims", Monitor.class);
    jettyDimensionMap.clear();
    if (dimensions == null || dimensions.isEmpty()) {
      return;
    }
    jettyDimensionMap.putAll(dimensions);
    MonitorUtils.addDimensionsToBuilder(builder, jettyDimensionMap);
  }

  private void emitJettyThreadPoolMetrics(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      Integer totalThreads,
      Integer idleThreads,
      boolean lowOnThreads,
      Integer minThreads,
      Integer maxThreads,
      Integer queueSize,
      Integer busyThreads
  )
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("threadPool", Monitor.class);
    jettyDimensionMap.put("threadPool", new String[]{String.valueOf(totalThreads)});

    if (totalThreads == null && idleThreads == null && minThreads == null && maxThreads == null
        && queueSize == null && busyThreads == null) {
      return;
    }
    if (totalThreads != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/total", totalThreads));
    }
    if (idleThreads != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/idle", idleThreads));
    }
    emitter.emit(builder.setMetric("jetty/threadPool/isLowOnThreads", lowOnThreads ? 1 : 0));
    if (minThreads != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/min", minThreads));
    }
    if (maxThreads != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/max", maxThreads));
    }
    if (queueSize != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/queueSize", queueSize));
    }
    if (busyThreads != null) {
      emitter.emit(builder.setMetric("jetty/threadPool/busy", busyThreads));
    }
  }

  public boolean emitServiceHeartbeat(ServiceEmitter emitter, Map<String, Object> heartbeatTags)
  {
    schedulerClassName = schedulerClassName == null ? "" : schedulerClassName;
    resolvedMonitorClasses.put("heartbeat", Monitor.class);
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (heartbeatTags != null && !heartbeatTags.isEmpty()) {
      heartbeatTags.forEach((key, value) -> {
        if (key != null && value != null) {
          jettyDimensionMap.put(key, new String[]{String.valueOf(value)});
          builder.setDimension(key, value);
        }
      });
    }
    emitter.emit(builder.setMetric("service/heartbeat", 1));
    return true;
  }
